package ltnc.auction.client.controller;
import javafx.application.Platform; import javafx.fxml.FXML; import javafx.scene.control.*; import ltnc.auction.client.net.AuctionSocketClient; import ltnc.auction.common.model.Auction; import ltnc.auction.common.protocol.*; import java.math.BigDecimal;
public class AuctionListController { @FXML private ListView<String> auctionList; @FXML private TextField usernameField; @FXML private TextField auctionIdField; @FXML private TextField amountField; @FXML private Label statusLabel;
 @FXML public void initialize(){auctionIdField.setText("auction-1");usernameField.setText("bidder-demo");loadAuctions();}
 @FXML private void loadAuctions(){new Thread(()->{try(AuctionSocketClient c=new AuctionSocketClient("localhost",5050)){Response r=c.send(new Request(RequestType.LIST_AUCTIONS,null,null,null,null));Platform.runLater(()->{auctionList.getItems().clear();if(r.isSuccess())for(Auction a:r.getAuctions())auctionList.getItems().add(a.getId()+" | "+a.getItem().getName()+" | "+a.getStatus()+" | "+a.getHighestPrice());statusLabel.setText(r.getMessage());});}catch(Exception e){Platform.runLater(()->statusLabel.setText("Không kết nối được server: "+e.getMessage()));}}).start();}
 @FXML private void placeBid(){try{String username=usernameField.getText().trim(),id=auctionIdField.getText().trim();BigDecimal amount=new BigDecimal(amountField.getText().trim());new Thread(()->{try(AuctionSocketClient c=new AuctionSocketClient("localhost",5050)){Response r=c.send(new Request(RequestType.PLACE_BID,username,null,id,amount));Platform.runLater(()->statusLabel.setText(r.getMessage()));if(r.isSuccess())loadAuctions();}catch(Exception e){Platform.runLater(()->statusLabel.setText("Lỗi: "+e.getMessage()));}}).start();}catch(NumberFormatException e){statusLabel.setText("Hãy nhập mức giá hợp lệ");}}
}
